transition:transform var(--dur-short,120ms) var(--ease-standard,cubic-bezier(.16,1,.3,1)),background-color var(--dur-short,120ms),opacity var(--dur-short,120ms);background:rgb(var(--c-accent, 255 108 28));color:rgb(var(--c-on-accent, 10 10 11));}.ds-button-primary:focus-visible{outline:2px solid rgb(var(--c-focus, 163 56 7));outline-offset:2px;}.ds-button-primary:active:not(:disabled){transform:scale(var(--motion-press,.97));filter:brightness(.95)}.ds-button-primary:disabled{opacity:.4;cursor:default}@media(hover:hover) and (pointer:fine){.ds-button-primary:hover:not(:disabled){filter:brightness(.95)}}@media(prefers-reduced-motion:reduce){.ds-button-primary:active:not(:disabled){transform:none}}

